package de.powerradio.studio;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;
public class RadioService extends Service {
static volatile int active=-1; MediaPlayer player;
public IBinder onBind(Intent i){return null;}
void refresh(){android.appwidget.AppWidgetManager m=android.appwidget.AppWidgetManager.getInstance(this);for(int id:m.getAppWidgetIds(new ComponentName(this,StudioWidget.class))){android.widget.RemoteViews v=new android.widget.RemoteViews(getPackageName(),R.layout.widget);for(int i=0;i<2;i++)v.setTextViewText(StudioWidget.plays[i],active==i?"■ STOP":"▶ PLAY");m.partiallyUpdateAppWidget(id,v);}}
public int onStartCommand(Intent intent,int flags,int id){int n=intent==null?-1:intent.getIntExtra("station",-1);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("radio","Radio",NotificationManager.IMPORTANCE_LOW));Intent stop=new Intent(this,RadioService.class).putExtra("station",-1);PendingIntent pi=PendingIntent.getService(this,99,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);startForeground(1,new Notification.Builder(this,"radio").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(n==1?"POWER RADIO POP":"POWER RADIO").addAction(android.R.drawable.ic_media_pause,"Stop",pi).setOngoing(true).build());if(n<0||n==active){stopSelf();return START_NOT_STICKY;}if(player!=null)player.release();active=n;refresh();try{player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource("https://stream.laut.fm/"+StudioWidget.stations[n]);player.setOnPreparedListener(p->{if(p==player)p.start();});player.setOnErrorListener((p,a,b)->{if(p==player)stopSelf();return true;});player.prepareAsync();}catch(Exception e){stopSelf();}return START_NOT_STICKY;}
public void onDestroy(){if(player!=null){player.release();player=null;}active=-1;refresh();stopForeground(true);super.onDestroy();}
}